package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="documents")
public class DocumentRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="event_id") private Long eventId; @Enumerated(EnumType.STRING) private DocumentType type; @Column(name="file_url") private String fileUrl; private String filename; @Column(name="uploaded_by") private Long uploadedBy; @Column(name="uploaded_at") private LocalDateTime uploadedAt = LocalDateTime.now(); private int version = 1; private boolean archived; @Column(name="archived_at") private LocalDateTime archivedAt; @Column(length=3000) private String description; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getEventId(){return eventId;} public void setEventId(Long eventId){this.eventId=eventId;} public DocumentType getType(){return type;} public void setType(DocumentType type){this.type=type;} public String getFileUrl(){return fileUrl;} public void setFileUrl(String fileUrl){this.fileUrl=fileUrl;} public String getFilename(){return filename;} public void setFilename(String filename){this.filename=filename;} public Long getUploadedBy(){return uploadedBy;} public void setUploadedBy(Long uploadedBy){this.uploadedBy=uploadedBy;} public LocalDateTime getUploadedAt(){return uploadedAt;} public void setUploadedAt(LocalDateTime uploadedAt){this.uploadedAt=uploadedAt;} public int getVersion(){return version;} public void setVersion(int version){this.version=version;} public boolean isArchived(){return archived;} public void setArchived(boolean archived){this.archived=archived;} public LocalDateTime getArchivedAt(){return archivedAt;} public void setArchivedAt(LocalDateTime archivedAt){this.archivedAt=archivedAt;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} }
